CREATE PROCEDURE "DA_KMEANS_CALL" (IN SCHEMANAME VARCHAR(100), IN SUFFIX VARCHAR(50), IN DATA_TABLE_NAME VARCHAR(50), IN CTL_TABLE_NAME VARCHAR(50)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  AS BEGIN     CREATE LOCAL TEMPORARY COLUMN TABLE #DA_KMEANS_ASSIGNED_TBL(ID INTEGER);     CREATE LOCAL TEMPORARY COLUMN TABLE #DA_KMEANS_CENTERS_TBL(ID INTEGER);     CREATE LOCAL TEMPORARY COLUMN TABLE #DA_KMEANS_SIL_CENTERS_TBL(ID INTEGER);     CREATE LOCAL TEMPORARY COLUMN TABLE #DA_KMEANS_STATISTIC_TBL(ID INTEGER);            DROP TABLE #DA_KMEANS_ASSIGNED_TBL;     DROP TABLE #DA_KMEANS_CENTERS_TBL;     DROP TABLE #DA_KMEANS_SIL_CENTERS_TBL;     DROP TABLE #DA_KMEANS_STATISTIC_TBL;     EXECUTE IMMEDIATE 'CREATE LOCAL TEMPORARY COLUMN TABLE #DA_KMEANS_ASSIGNED_TBL LIKE DA_KMEANS_ASSIGNED_T_'|| :SUFFIX;     EXECUTE IMMEDIATE 'CREATE LOCAL TEMPORARY COLUMN TABLE #DA_KMEANS_CENTERS_TBL LIKE DA_KMEANS_CENTERS_T_'|| :SUFFIX;     EXECUTE IMMEDIATE 'CREATE LOCAL TEMPORARY COLUMN TABLE #DA_KMEANS_SIL_CENTERS_TBL LIKE DA_KMEANS_SIL_CENTERS_T_'|| :SUFFIX;     EXECUTE IMMEDIATE 'CREATE LOCAL TEMPORARY COLUMN TABLE #DA_KMEANS_STATISTIC_TBL LIKE DA_KMEANS_STATISTIC_T_'|| :SUFFIX;     EXECUTE IMMEDIATE 'CALL DA_KMEANS_PROC_' || :SUFFIX || '(' || :DATA_TABLE_NAME || ',' || :CTL_TABLE_NAME || ', #DA_KMEANS_ASSIGNED_TBL, #DA_KMEANS_CENTERS_TBL, #DA_KMEANS_SIL_CENTERS_TBL, #DA_KMEANS_STATISTIC_TBL) WITH OVERVIEW';     SELECT * FROM #DA_KMEANS_ASSIGNED_TBL;     SELECT * FROM #DA_KMEANS_CENTERS_TBL;     SELECT * FROM #DA_KMEANS_SIL_CENTERS_TBL;     SELECT * FROM #DA_KMEANS_STATISTIC_TBL;     DROP TABLE #DA_KMEANS_ASSIGNED_TBL;     DROP TABLE #DA_KMEANS_CENTERS_TBL;     DROP TABLE #DA_KMEANS_SIL_CENTERS_TBL;     DROP TABLE #DA_KMEANS_STATISTIC_TBL; END
